  if (!gateCheck.ok) return json({ok:false, error:gateCheck.error || 'Canonical FS27/SkyGate bearer could not be introspected.', skygate:gateCheck.data || null}, gateCheck.status || 401);
  if (!allowsAdminGate(gateCheck.data, env)) return json({ok:false, error:'Canonical FS27/SkyGate bearer is active but not admin-scoped for 0S owner access.', skygate:gateCheck.data || null}, 403);
  gateData = gateCheck.data || gateData || {};
