async function resolveOwnerSessionFromRequest(request, env) {
  const presented = presentedGateCredentials(request);
  if (!presented.length) return {ok:false};
  const acceptedCodes = ownerAdminAcceptedCodes(env);
  if (acceptedCodes.length && presented.some(value => acceptedCodes.includes(value))) {
    const matched = presented.find(value => acceptedCodes.includes(value));
    const gateLogin = await loginFs27Gate(matched, env);
    if (!gateLogin.ok || !gateLogin.data?.token) return {ok:false};
    const gate = await introspectAnyGateToken(gateLogin.data.token, env);
    if (!gate.ok || !allowsAdminGate(gate.data, env)) return {ok:false};
    const now = Math.floor(Date.now() / 1000);
    const maxAge = gate.data?.exp ? Math.max(0, Number(gate.data.exp) - now) : 12 * 60 * 60;
    return {
      ok:true,
      session:{
        token:gateLogin.data.token,
        expiresAt:gate.data?.exp ? new Date(gate.data.exp * 1000).toISOString() : '',
        maxAge,
        identity:gateIdentity(gate.data || {}, env)
      },
      cookies:ownerAdminCookies(gateLogin.data.token, maxAge),
      via:'fs27-skygate-admin-login'
    };
  }
  for (const token of presented) {
    const gate = await introspectAnyGateToken(token, env);
    if (gate.ok && allowsAdminGate(gate.data, env)) {
      return {
        ok:true,
        session:{
          token,
          expiresAt: gate.data?.exp ? new Date(gate.data.exp * 1000).toISOString() : '',
          maxAge: 0,
          identity: gateIdentity(gate.data || {}, env)
        },
        cookies:[],
        via:gate.via || 'skygate'
      };
    }
  }
  return {ok:false};
}
