async function aeFlowUpdateSummary(env, patch = {}) {
  const current = await aeFlowReadSummary(env) || {
    schema: 'metraiyux.ae-flowpro.founder-workspace-summary.v1',
    app_id: AE_FLOW_APP_ID,
    workspace_id: aeFlowWorkspaceId(env),
    founder_only: true,
    contact_events: 0,
    imports: [],
    tables: {},
    source_counts: {},
    created_at: aeFlowNow()
  };
  const next = {
    ...current,
    workspace_id: aeFlowWorkspaceId(env),
    updated_at: aeFlowNow(),
    storage: aeFlowStorageStatus(env)
  };
  if (patch.table) {
    next.tables = {...(next.tables || {})};
    next.tables[patch.table] = Number(next.tables[patch.table] || 0) + Number(patch.count || 1);
  }
  if (patch.source) {
    next.source_counts = {...(next.source_counts || {})};
    next.source_counts[patch.source] = Number(next.source_counts[patch.source] || 0) + Number(patch.count || 1);
  }
  if (patch.import) {
    next.imports = [patch.import, ...(next.imports || [])].slice(0, 50);
  }
  if (patch.contacts) next.contact_events = Number(next.contact_events || 0) + Number(patch.contacts || 0);
  await aeFlowWriteSummary(env, next);
  return next;
}
