    appId: AE_FLOW_APP_ID,
    workspaceId,
    table,
    recordId: aeFlowText(recordId || row.id || `${table}_${Date.now()}`, 240),
    operation: 'upsert',
    checksum,
    payload: row,
    primary: {ok:true, system:'citadeldb-cloudflare-d1', writtenAt:aeFlowNow()},
    citadel: {ok:true, storage:'cloudflare_d1', writtenAt:aeFlowNow()},
