async function aeFlowFounderRuntime(request, env, ctx, auth, url) {
  const suffix = url.pathname.slice(AE_FLOW_RUNTIME_PREFIX.length) || '/status';
  const method = request.method.toUpperCase();
  if (suffix === '/status' && method === 'GET') {
    const summary = await aeFlowUpdateSummary(env, {count:0});
    return json(aeFlowRuntimeStatus(summary));
  }
  if (method === 'GET') {
    const table = suffix === '/journal' ? 'journal' : suffix === '/snapshots' ? 'snapshots' : '';
    if (!table) return json({ok:false, error:'ae_flow_runtime_route_not_found'}, 404);
    const rows = await aeFlowRows(env, table, Number(url.searchParams.get('limit') || 50));
    return json({ok:rows.ok, [table]:rows.rows.map((row) => row.payload).filter(Boolean), count:rows.rows.length, storage:aeFlowStorageStatus(env)});
  }
  if (method === 'DELETE' && suffix === '/journal') {
    const result = await aeFlowRuntimeRecord(env, 'journal', 'journal', {type:'journal-clear-request', cleared_at:aeFlowNow()}, founderActor(auth));
    return json({ok:true, cleared:false, retained:true, message:'Founder CRM journal is append-only; a clear request was recorded instead of deleting history.', status:result.status});
  }
  if (method !== 'POST') return json({ok:false, error:'Method not allowed'}, 405);
  const body = await readJson(request);
  if (suffix === '/journal') {
    const result = await aeFlowRuntimeRecord(env, 'journal', 'journal', body, founderActor(auth));
    return json({ok:true, entry:result.payload, status:result.status}, 201);
  }
  if (suffix === '/snapshots') {
    const result = await aeFlowRuntimeRecord(env, 'snapshots', 'snapshot', body, founderActor(auth));
    return json({ok:true, snapshot:result.payload, status:result.status}, 201);
  }
  if (suffix === '/activation-packs') {
    const result = await aeFlowRuntimeRecord(env, 'activation_packs', 'activationPack', body, founderActor(auth));
    return json({ok:true, activationPack:result.payload, status:result.status}, 201);
  }
  if (suffix === '/activation-workflows') {
    const result = await aeFlowRuntimeRecord(env, 'activation_workflows', 'activationWorkflow', body, founderActor(auth));
    return json({ok:true, activationWorkflow:result.payload, status:result.status}, 201);
  }
  const executionMatch = suffix.match(/^\/activation-workflows\/([^/]+)\/execution$/);
  if (executionMatch) {
    const result = await aeFlowRuntimeRecord(env, 'execution_board', 'executionItem', {...body, workflowId:decodeURIComponent(executionMatch[1])}, founderActor(auth));
    return json({ok:true, executionItem:result.payload, status:result.status}, 201);
  }
  const dispatchMatch = suffix.match(/^\/execution-board\/([^/]+)\/dispatch$/);
  if (dispatchMatch) {
    const result = await aeFlowRuntimeRecord(env, 'dispatch_board', 'dispatch', {...body, executionItemId:decodeURIComponent(dispatchMatch[1])}, founderActor(auth));
    return json({ok:true, dispatch:result.payload, status:result.status}, 201);
  }
  return json({ok:false, error:'ae_flow_runtime_route_not_found', path:suffix}, 404);
}
function aeFlowBackupRecords(body = {}) {
  const backup = body.backup && typeof body.backup === 'object' ? body.backup : body;
  const collections = ['visits', 'accounts', 'deals', 'handoff_log'];
  const records = [];
  for (const collection of collections) {
    const items = Array.isArray(backup[collection]) ? backup[collection] : [];
    for (const item of items) records.push({raw:item, collection, source:body.source || `backup:${collection}`, kind:collection.replace(/_log$/, '')});
  }
  return records;
}
async function aeFlowImportRecords(env, records = [], source = 'manual-import', actor = 'owner-admin') {
  const accepted = [];
  const skipped = [];
  for (const item of records) {
    const contact = aeFlowContactFromInput(item, {source:item.source || source, collection:item.collection, kind:item.kind});
    if (!contact) {
      skipped.push({collection:item.collection || '', reason:'no_contact_signal'});
      continue;
    }
    contact.workspace_id = aeFlowWorkspaceId(env);
    const stored = await aeFlowWritePrivateRecord(env, 'contacts', contact.id, contact, actor);
    accepted.push({id:contact.id, source:contact.source, collection:contact.collection, stored:Boolean(stored.ok)});
  }
  const byCollection = accepted.reduce((out, item) => {
    out[item.collection || 'unknown'] = (out[item.collection || 'unknown'] || 0) + 1;
    return out;
  }, {});
  const importRecord = {
    id: aeFlowRuntimeId('ae_import'),
    source,
    accepted: accepted.length,
    skipped: skipped.length,
    by_collection: byCollection,
    created_at: aeFlowNow()
  };
  const summary = await aeFlowUpdateSummary(env, {
    table:'contacts',
    source,
    contacts:accepted.length,
    count:accepted.length,
    import:importRecord
  });
  return {accepted, skipped, importRecord, summary};
}
async function founderCommandAeFlow(request, env, ctx, auth, url) {
  if (!url.pathname.startsWith(AE_FLOW_API_PREFIX)) return null;
  if (url.pathname.startsWith(AE_FLOW_RUNTIME_PREFIX)) return aeFlowFounderRuntime(request, env, ctx, auth, url);
  const method = request.method.toUpperCase();
  const suffix = url.pathname.slice(AE_FLOW_API_PREFIX.length) || '/status';
  if ((suffix === '/status' || suffix === '/workspace') && method === 'GET') {
    const summary = await aeFlowUpdateSummary(env, {count:0});
    return json({
      ok:true,
      app_id:AE_FLOW_APP_ID,
      workspace_id:aeFlowWorkspaceId(env),
      founder_only:true,
      noindex:true,
      storage:aeFlowStorageStatus(env),
      summary,
      runtime:aeFlowRuntimeStatus(summary),
      products:AE_FLOW_SYNC_PRODUCTS,
      routes:{
        contacts:`${AE_FLOW_API_PREFIX}/contacts`,
        import_batch:`${AE_FLOW_API_PREFIX}/import-batch`,
        runtime_status:`${AE_FLOW_RUNTIME_PREFIX}/status`
      }
    });
  }
  if (suffix === '/products' && method === 'GET') return json({ok:true, products:AE_FLOW_SYNC_PRODUCTS, skyepay:'https://skyegatefs27-citadeldb.graylondonskyes.workers.dev/skyepay-store.html?client=metraiyux-0s'});
  if (suffix === '/contacts' && method === 'GET') {
    const rows = await aeFlowRows(env, 'contacts', Number(url.searchParams.get('limit') || 50));
    const detail = url.searchParams.get('detail') === '1';
    return json({ok:rows.ok, workspace_id:aeFlowWorkspaceId(env), contacts:rows.rows.map((row) => aeFlowContactForResponse(row.payload || {}, detail)), count:rows.rows.length, storage:aeFlowStorageStatus(env)});
  }
  if ((suffix === '/contact' || suffix === '/capture') && method === 'POST') {
    const body = await readJson(request);
    const captured = await aeFlowCaptureSystemContact(env, {...body, source:body.source || 'founder-command-manual'}, auth);
    return json({ok:captured.ok, captured:{contact_id:captured.contact_id, source:captured.source}, storage:aeFlowStorageStatus(env)}, captured.ok ? 201 : 400);
  }
  if (suffix === '/import-batch' && method === 'POST') {
    const body = await readJson(request);
    const records = Array.isArray(body.records) ? body.records : aeFlowBackupRecords(body);
    if (records.length > AE_FLOW_IMPORT_MAX_BATCH) return json({ok:false, error:'ae_flow_import_batch_too_large', max:AE_FLOW_IMPORT_MAX_BATCH, received:records.length}, 413);
    const result = await aeFlowImportRecords(env, records, aeFlowText(body.source || 'founder-backup-import', 160), founderActor(auth));
    return json({
      ok:true,
      workspace_id:aeFlowWorkspaceId(env),
      imported:{accepted:result.accepted.length, skipped:result.skipped.length, by_collection:result.importRecord.by_collection},
      storage:aeFlowStorageStatus(env),
      summary:result.summary
    }, 201);
  }
  if (suffix === '/import' && method === 'POST') {
    const body = await readJson(request);
    const records = aeFlowBackupRecords(body);
    if (records.length > AE_FLOW_IMPORT_MAX_BATCH) {
      return json({ok:false, batch_required:true, max_batch:AE_FLOW_IMPORT_MAX_BATCH, total_records:records.length, route:`${AE_FLOW_API_PREFIX}/import-batch`}, 413);
    }
    const result = await aeFlowImportRecords(env, records, aeFlowText(body.source || 'founder-backup-import', 160), founderActor(auth));
    return json({ok:true, workspace_id:aeFlowWorkspaceId(env), imported:{accepted:result.accepted.length, skipped:result.skipped.length, by_collection:result.importRecord.by_collection}, storage:aeFlowStorageStatus(env), summary:result.summary}, 201);
  }
  return json({ok:false, error:'AE Flow founder CRM route not found', route:AE_FLOW_API_PREFIX}, 404);
}
