function founderCompactHash(value, length = 16) {
  const text = String(value || '');
  if (!text) return '';
  return text.length > length ? `${text.slice(0, length)}...` : text;
}

async function founderReadJsonAsset(request, env, asset) {
  if (!env.ASSETS?.fetch) {
    return { ok:false, status:503, error:'0S static asset binding is not configured.', asset };
	  }
	  try {
	    const response = await env.ASSETS.fetch(new Request(`https://0s-assets.local${asset.pathname}`, {method:'GET'}));
	    const text = await response.text();
    if (!response.ok) {
      return { ok:false, status:response.status || 404, error:`${asset.label} returned ${response.status}.`, asset };
    }
    return { ok:true, status:response.status, asset, data:JSON.parse(text) };
  } catch (error) {
    return { ok:false, status:502, error:error?.message || `Could not read ${asset.label}.`, asset };
  }
}

