async function founderCommandRepoVaultDownload(request, env, url) {
  if (request.method !== 'POST') return json({ok:false, error:'Method not allowed'}, 405);
  const payload = await founderRepoVaultPayload(request, env);
  const upload = payload.latest_upload || {};
  const fullArtifact = payload.project_manifest?.encrypted_full_artifact || {};
  const receiptId = String(upload.receipt_id || fullArtifact.receipt_id || '').trim();
  const origin = founderRepoVaultDropOrigin(env);
  const recoveryUrl = founderRepoVaultReceiptUrl(upload.recovery_url || fullArtifact.recovery_url || `${origin}/#client-vault`, receiptId);
  if (!receiptId) {
    const response = json({
      ok:false,
      error:'No encrypted full-repo backup receipt is published yet.',
      recovery_url: recoveryUrl,
      safety:{ shared_gate_required:true, raw_file_bodies_exposed:false, secret_values_exposed:false }
    }, 404);
    response.headers.set('cache-control', 'no-store');
    return response;
  }
  const expiresInSeconds = Math.min(3600, Math.max(300, Number(url.searchParams.get('expires') || env.SKYEVAULT_DOWNLOAD_LINK_SECONDS || 900) || 900));
  const portalKey = routexFirstEnv(env, ['SKYEVAULT_PORTAL_KEY','CLIENT_PORTAL_KEY']);
  const clientBody = {
    action:'download',
    receiptId,
    clientEmail: founderRepoVaultOwnerEmail(env),
    expiresInSeconds
  };
  const adminBody = {
    receiptId,
    expiresInSeconds
  };
  if (portalKey) clientBody.portalKey = portalKey;
  const attempts = [];
  let upstream = {ok:false, status:0};
  let upstreamBody = {};
  let upstreamRoute = '/api/client-vault';
  let upstreamOrigin = '';
  const origins = founderRepoVaultDropOrigins(env);
  const clientRoutes = ['/api/client-vault','/.netlify/functions/client-vault'];
  clientLoop:
  for (const candidateOrigin of origins) {
    for (const candidateRoute of clientRoutes) {
      const response = await fetch(`${candidateOrigin}${candidateRoute}`, {
        method:'POST',
        headers:founderRepoVaultClientDownloadHeaders(request, env),
        body:JSON.stringify(clientBody)
      });
      const bodyResult = await response.json().catch(() => ({}));
      attempts.push({
        origin:candidateOrigin,
        route:candidateRoute,
        status:response.status,
        ok:response.ok,
        has_download:Boolean(bodyResult.downloadUrl),
        error:bodyResult.error || bodyResult.warning || ''
      });
      upstream = response;
      upstreamBody = {
        ...bodyResult,
        client_error: bodyResult.error || bodyResult.warning || '',
        client_status: response.status
      };
      upstreamRoute = candidateRoute;
      upstreamOrigin = candidateOrigin;
      if (response.ok && bodyResult.downloadUrl) break clientLoop;
    }
  }
  if (!upstream.ok || adminUpstreamBodyMissingDownload(upstreamBody)) {
    const adminRoutes = ['/api/admin-vault-download','/.netlify/functions/admin-vault-download'];
    const adminHeaders = founderRepoVaultDownloadHeaders(request);
    const serverGateToken = founderRepoVaultSharedGateToken(request, env);
    if (serverGateToken) {
      if (!adminHeaders.has('authorization')) adminHeaders.set('authorization', `Bearer ${serverGateToken}`);
      if (!adminHeaders.has('x-free99-gate-session')) adminHeaders.set('x-free99-gate-session', serverGateToken);
      if (!adminHeaders.has('x-skye-gate-session')) adminHeaders.set('x-skye-gate-session', serverGateToken);
      if (!adminHeaders.has('x-free99-admin-code')) adminHeaders.set('x-free99-admin-code', serverGateToken);
    }
    adminLoop:
    for (const candidateOrigin of origins) {
      for (const candidateRoute of adminRoutes) {
        const response = await fetch(`${candidateOrigin}${candidateRoute}`, {
          method:'POST',
          headers:adminHeaders,
          body:JSON.stringify(adminBody)
        });
        const bodyResult = await response.json().catch(() => ({}));
        attempts.push({
          origin:candidateOrigin,
          route:candidateRoute,
          status:response.status,
          ok:response.ok,
          has_download:Boolean(bodyResult.downloadUrl),
          error:bodyResult.error || bodyResult.warning || ''
        });
        if (response.ok && bodyResult.downloadUrl) {
          upstream = response;
          upstreamBody = bodyResult;
          upstreamRoute = candidateRoute;
          upstreamOrigin = candidateOrigin;
          break adminLoop;
        }
        upstreamBody = {
          ...upstreamBody,
          admin_error: bodyResult.error || bodyResult.warning || upstreamBody.admin_error || '',
          admin_status: response.status,
          attempts
        };
      }
    }
  }
  let response;
  if (!upstream.ok || upstreamBody.ok === false || !upstreamBody.downloadUrl) {
    response = json({
      ok:false,
      status:upstream.status,
      error:upstreamBody.error || upstreamBody.client_error || upstreamBody.admin_error || upstreamBody.warning || 'The vault accepted the receipt but did not return a download link.',
      admin_error:upstreamBody.admin_error || '',
      admin_status:upstreamBody.admin_status || null,
      client_error:upstreamBody.client_error || '',
      client_status:upstreamBody.client_status || null,
      receipt_id:receiptId,
      recovery_url:recoveryUrl,
      vault_route:upstreamRoute,
      vault_origin:upstreamOrigin,
      attempts,
      safety:{
        shared_gate_required:true,
        raw_file_bodies_exposed:false,
        secret_values_exposed:false,
        signed_url_persisted:false
      }
    }, upstream.ok ? 502 : upstream.status || 502);
  } else {
    const item = upstreamBody.item || {};
    response = json({
      ok:true,
      receipt_id:receiptId,
      file_name:item.fileName || `MetrAIyux-0S-full-repo-${receiptId}.tar.zst.enc`,
      artifact_bytes:Number(item.fileSize || upload.artifact_bytes || fullArtifact.artifact_bytes || 0) || null,
      artifact_human:fullArtifact.artifact_human || '',
      artifact_sha256_prefix:upload.artifact_sha256_prefix || fullArtifact.artifact_sha256_prefix || '',
      recovery_url:recoveryUrl,
      download_url:upstreamBody.downloadUrl,
      expires_at:upstreamBody.expiresAt || '',
      route:'/api/founder-command/repo-vault/download',
      vault_route:upstreamRoute,
      vault_origin:upstreamOrigin,
      safety:{
        shared_gate_required:true,
        signed_download:true,
        raw_file_bodies_exposed:false,
        secret_values_exposed:false,
        signed_url_persisted:false,
        note:'The signed URL is returned only to the authenticated Founder Command browser and expires shortly.'
      }
    });
  }
  response.headers.set('cache-control', 'no-store');
  return response;
}

async function founderCommandRepoVault(request, env, url) {
  if (request.method !== 'GET') return json({ok:false, error:'Method not allowed'}, 405);
  const chunkId = String(url.searchParams.get('chunk') || '').trim();
  if (chunkId) {
    if (!/^(?:entries|private|skipped)-\d{3}$/.test(chunkId)) {
      return json({ok:false, error:'Unknown repo vault manifest chunk.'}, 404);
    }
    const asset = {
      id: chunkId,
      label: `Repo vault manifest chunk ${chunkId}`,
      pathname: `/proof/repo-vault-project-manifest/${chunkId}.json`,
      kind: 'project manifest chunk'
    };
    const result = await founderReadJsonAsset(request, env, asset);
    return json({
      ok: result.ok,
      file: { id: asset.id, label: asset.label, href: asset.pathname, kind: asset.kind },
      safety: { raw_file_bodies_exposed:false, secret_values_exposed:false },
      data: result.data || null,
      error: result.error || null
    }, result.ok ? 200 : result.status || 502);
  }
  const fileId = String(url.searchParams.get('file') || '').trim();
  if (fileId) {
    const asset = Object.values(FOUNDER_REPO_VAULT_ASSETS).find(item => item.id === fileId || item.pathname === fileId);
    if (!asset) return json({ok:false, error:'Unknown repo vault stream file.', allowed:Object.values(FOUNDER_REPO_VAULT_ASSETS).map(item => item.id)}, 404);
    const result = await founderReadJsonAsset(request, env, asset);
    return json({
      ok: result.ok,
      file: { id: asset.id, label: asset.label, href: asset.pathname, kind: asset.kind },
      safety: { raw_file_bodies_exposed:false, secret_values_exposed:false },
      data: result.data || null,
      error: result.error || null
    }, result.ok ? 200 : result.status || 502);
  }
  const payload = await founderRepoVaultPayload(request, env);
  return json({ok:true, ...payload});
}
