async function founderCommandSkyEmailPocket(request, env, ctx, auth, url) {
  if (request.method !== 'GET') return json({ok:false, error:'Method not allowed'}, 405);
  const ownerRecord = await zeroOsReadOwnerSkyEmail(env);
  const mailboxEmail = zeroOsGateCleanEmail(url.searchParams.get('mailbox_email') || ownerRecord?.mailbox_email || zeroOsOwnerSkyEmailDefault(env));
  const workspaceId = founderCleanText(url.searchParams.get('workspace_id') || ownerRecord?.workspace_id || 'metraiyux-0s-owner', 160);
  const serviceToken = founderSkyEmailServiceToken(env);
  let summary = null;
  let mode = 'unavailable';
  let error = '';
  if (serviceToken) {
    const params = new URLSearchParams();
    if (mailboxEmail) params.set('mailbox_email', mailboxEmail);
    if (workspaceId) params.set('workspace_id', workspaceId);
    const result = await founderSkyEmailServiceSummary(env, params, serviceToken);
    summary = result.data;
    mode = 'service-summary';
    error = result.ok ? '' : founderCleanText(result.data?.error || `SkyeMail returned ${result.response?.status || 0} from ${result.route}`, 500);
  } else {
    const gateToken = founderGateTokenFromRequest(request, {});
    const skyemailToken = await founderSkyEmailSessionToken(env, gateToken, {
      email:mailboxEmail,
      mailbox:{requested_email:mailboxEmail},
      reason:'founder-command-pocket-skyemail'
    });
    if (skyemailToken) {
      const [statusRes, labelsRes, inboxRes] = await Promise.all([
        founderSkyEmailPlatformRequest(env, '/mail-status', {headers:{authorization:`Bearer ${skyemailToken}`}}),
        founderSkyEmailPlatformRequest(env, '/gmail-labels', {headers:{authorization:`Bearer ${skyemailToken}`}}),
        founderSkyEmailPlatformRequest(env, '/gmail-list?max=8&label=INBOX', {headers:{authorization:`Bearer ${skyemailToken}`}})
      ]);
      const [status, labels, inbox] = await Promise.all([
        statusRes.json().catch(() => ({})),
        labelsRes.json().catch(() => ({})),
        inboxRes.json().catch(() => ({}))
      ]);
      summary = {
        ok:statusRes.ok && status?.ok !== false,
        status,
        labels:labels.items || [],
        recent_messages:inbox.items || [],
        mailbox:status.mailbox || {mailbox_email:mailboxEmail}
      };
      mode = 'gate-session';
      error = summary.ok ? '' : founderCleanText(status.error || `SkyeMail returned ${statusRes.status}`, 500);
    } else {
      error = 'Founder Command needs SKYMAIL_SERVICE_TOKEN or a gate token that can mint a SkyeMail session for pocket inbox sync.';
    }
  }
  return json({
    ok:!error,
    mode,
    error,
    origin:founderSkyEmailOrigin(env),
    owner_record:ownerRecord,
    mailbox_email:mailboxEmail,
    workspace_id:workspaceId,
    summary,
    links:{
      inbox:founderSkyEmailHandoffPath('dashboard.html'),
      compose:founderSkyEmailHandoffPath('compose.html'),
      onboarding:founderSkyEmailHandoffPath('onboarding.html'),
      handoffs:'/founder-command/?view=mailboxes#workspace-handoffs'
    },
    route:'/api/founder-command/skyemail/pocket'
  });
}
