  const link = founderCommandIdentityLinkFromBody(body, resolution.account, auth);
  if (!link.source_system || !link.id_value) return json({ok:false, error:'source_system_and_source_id_required'}, 400);
  const index = await founderCommandPutIdentityLink(env, link);
  const citadel = await founderCommandMirrorAccountRow(env, 'client_identity_links', link.id, link, auth);
  await commandBridgeAppendEvent(env, {
    source_app:'founder-command',
    source_surface:'identity',
    event_type:'founder_command.identity.link',
    status:'recorded',
    summary:`Founder identity link: ${resolution.account.display_name} -> ${link.source_system}`,
    actor:founderActor(auth),
    entity:{kind:'client-identity-link', id:link.id, label:resolution.account.display_name},
    ids:{client_account_id:link.client_account_id, source_system:link.source_system, source_id:link.source_id || link.id_value},
    metadata:{citadel:citadel.ok ? 'ok' : 'fallback', workspace_id:FOUNDER_OWNER_WORKSPACE_ID}
  }, auth).catch(() => null);
