  const account = payload.accounts.find((item) => item.client_account_id === cleanId || item.ids?.client_id === cleanId || item.ids?.valley_business_id === cleanId);
  if (!account) return {ok:false, error:'founder_account_not_found', account_id:cleanId, status:404};
