function routexAeWeekKey(value = routexNow()) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return new Date().toISOString().slice(0, 10);
  const day = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() - day + 1);
  return date.toISOString().slice(0, 10);
}
function routexAeFounderAccessHours(startAt, endAt, fallbackMinutes = 60) {
  const start = Date.parse(startAt || '');
  const end = Date.parse(endAt || '');
  if (Number.isFinite(start) && Number.isFinite(end) && end > start) return Math.min(10, Math.max(0.25, (end - start) / 3600000));
  return Math.max(0.25, Math.min(10, Number(fallbackMinutes || 60) / 60));
}
