  if (job.acceptance_mode === 'single' && acceptedCount >= 1) return {ok:false, status:409, error:'Single-acceptance lock blocked over-assignment.'};
  if (acceptedCount >= Number(job.slots || 0)) return {ok:false, status:409, error:'Slot cap blocked over-assignment.'};
