  const providerNotification = routexNotify(state, job.provider_id, options.confirmed ? 'Job claimed by AE' : 'AE selected for job', `${workerUser.name || workerUser.email || workerUser.id} is attached to ${job.title}.`);
  await routexDispatchNotificationProvider(env, state, workerNotification);
  await routexDispatchNotificationProvider(env, state, providerNotification);
