function musicSkyeNetRouteSlug(value, fallback = 'artist') {
  const normalizedFallback = musicSlug(fallback, 'artist').slice(0, 70) || 'artist';
  let slug = musicSlug(value || normalizedFallback, normalizedFallback).slice(0, 88).replace(/-+$/g, '');
  if (!slug || ['api','admin','assets','musicnexus','skyenet','skynet','drops','artists','static'].includes(slug)) {
    slug = `${normalizedFallback}-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}`;
  }
  return slug.slice(0, 88).replace(/-+$/g, '') || normalizedFallback;
}
function musicArtistStorefrontRouteSlug(body = {}, store = {}, artist = {}) {
  const requested = musicText(body.skyeNetSlug || body.skyenetSlug || body.routeSlug || body.urlSlug || body.slug || body.name || '', '', 140);
  return musicSkyeNetRouteSlug(requested || store.skyeNetRouteSlug || store.slug || artist.slug || artist.name || store.artistName || store.artistId || artist.id || 'artist', 'artist');
}
function musicStorefrontMoneyLabel(cents = 0, currency = 'USD') {
  const amount = (Number(cents || 0) / 100).toFixed(2);
  return `${String(currency || 'USD').toUpperCase()} ${amount}`;
}
function musicArtistStorefrontPublicData(store = {}, artist = {}, state = {}, publish = {}) {
  const artistId = store.artistId || artist.artistId || artist.id || '';
  const activeProducts = (state.store?.products || [])
    .filter(product => product.artistId === artistId && product.status !== 'archived' && product.status !== 'deleted')
    .slice(0, 48);
  const releases = (state.releases || [])
    .filter(release => !artistId || release.artistId === artistId)
    .slice(0, 24);
  const drops = (state.drops?.items || [])
    .filter(drop => !artistId || drop.artistId === artistId)
    .slice(0, 24);
  const assets = (state.assets || [])
    .filter(asset => !artistId || asset.artistId === artistId)
    .slice(0, 48);
  const assetById = new Map(assets.map(asset => [asset.id || asset.assetId, asset]));
  const trackRows = [];
  for (const release of releases) {
    for (const [index, track] of musicTrackList(release.tracks).entries()) {
      const asset = assetById.get(track.assetId) || {};
      trackRows.push({
        id:`${release.id || 'release'}-${index + 1}`,
        title:musicText(track.title || release.title || `Track ${index + 1}`, '', 160),
        releaseTitle:musicText(release.title || '', '', 160),
        previewUrl:musicText(track.previewUrl || track.streamUrl || asset.previewUrl || asset.streamUrl || '', '', 1000),
        gatedStreamUrl:musicText(asset.streamUrl || track.streamUrl || '', '', 1000),
        duration:Number(track.duration || asset.duration || 0) || 0,
        rightsStatus:musicText(release.rights?.status || '', '', 80)
      });
    }
  }
  for (const drop of drops) {
    for (const [index, track] of (drop.tracks || []).entries()) {
      trackRows.push({
        id:`${drop.dropId || drop.id || 'drop'}-${index + 1}`,
        title:musicText(track.title || drop.title || `Drop track ${index + 1}`, '', 160),
        releaseTitle:musicText(drop.title || '', '', 160),
        previewUrl:musicText(track.previewUrl || track.streamUrl || '', '', 1000),
        gatedStreamUrl:musicText(track.streamUrl || '', '', 1000),
        duration:Number(track.duration || 0) || 0,
        rightsStatus:musicText(drop.rightsStatus || '', '', 80)
      });
    }
  }
  for (const product of activeProducts) {
    if (!product.previewUrl && !product.streamUrl) continue;
    trackRows.push({
      id:`${product.productId || product.id || 'product'}-preview`,
      title:musicText(product.title || 'Store preview', '', 160),
      releaseTitle:'Artist store preview',
      previewUrl:musicText(product.previewUrl || product.streamUrl || '', '', 1000),
      gatedStreamUrl:'',
      duration:0,
      rightsStatus:'storefront-preview'
    });
  }
  const tracks = [];
  const seen = new Set();
  for (const track of trackRows) {
    const key = `${track.title}|${track.previewUrl}|${track.releaseTitle}`;
    if (seen.has(key)) continue;
    seen.add(key);
    tracks.push(track);
    if (tracks.length >= 36) break;
  }
  return {
    schema:'skymusicnexus.artist-storefront.static.v1',
    generatedAt:musicNow(),
    artist:{
      id:artistId,
      slug:musicText(artist.slug || store.slug || '', '', 120),
      name:musicText(artist.name || store.artistName || store.name || 'Artist', 'Artist', 180),
      bio:musicText(store.bio || artist.bio || 'Artist storefront powered by SkyeMusicNexus.', '', 1400),
      genre:Array.isArray(artist.genre) ? artist.genre.slice(0, 12) : String(artist.genre || '').split(',').map(item => item.trim()).filter(Boolean).slice(0, 12),
      email:musicText(artist.email || store.fulfillmentEmail || '', '', 180)
    },
    store:{
      id:store.storeId || '',
      name:musicText(store.name || `${artist.name || store.artistName || 'Artist'} Nexus Store`, '', 180),
      slug:musicText(store.slug || '', '', 120),
      status:musicText(store.status || 'active', 'active', 80),
      plan:musicStorefrontPlan(store.storefrontPlan || store.planId),
      feeMode:musicFeeMode(store.feeMode),
      supportUrl:musicText(store.supportUrl || '', '', 1000),
      skyePayTrackingRef:musicText(artist.skyepay?.trackingRef || musicArtistSkyePayRef(artistId), '', 160)
    },
    publish,
    stats:{
      products:activeProducts.length,
      releases:releases.length,
      drops:drops.length,
      playablePreviews:tracks.filter(track => track.previewUrl).length
    },
    products:activeProducts.map(product => ({
      id:product.productId || product.id || '',
      title:musicText(product.title || 'Store item', '', 220),
      description:musicText(product.description || '', '', 900),
      productType:musicText(product.productType || product.type || 'digital', 'digital', 80),
      priceCents:Number(product.priceCents || 0) || 0,
      currency:musicText(product.currency || 'USD', 'USD', 8).toUpperCase(),
      imageUrl:musicText(product.imageUrl || product.coverArtUrl || '', '', 1000),
      fulfillmentType:musicText(product.fulfillmentType || 'manual', 'manual', 80),
      status:musicText(product.status || 'active', 'active', 80),
      gatedCheckoutUrl:`/SkyeMusicNexus/public/store.html?artistId=${encodeURIComponent(artistId)}&productId=${encodeURIComponent(product.productId || product.id || '')}`
    })),
    releases:releases.map(release => ({
      id:release.id || '',
      title:musicText(release.title || 'Release', '', 220),
      type:musicText(release.type || 'release', 'release', 80),
      status:musicText(release.status || '', '', 80),
      rightsStatus:musicText(release.rights?.status || '', '', 80),
      trackCount:musicTrackList(release.tracks).length
    })),
    drops:drops.map(drop => ({
      id:drop.dropId || drop.id || '',
      title:musicText(drop.title || 'Drop', '', 220),
      slug:musicText(drop.slug || '', '', 120),
      rightsStatus:musicText(drop.rightsStatus || '', '', 80),
      visibility:musicText(drop.visibility || 'public', 'public', 80)
    })),
    tracks,
    links:{
      nexusStore:'/SkyeMusicNexus/public/store.html',
      nexusPlayer:'/SkyeMusicNexus/public/player.html',
      nexusSignup:'/SkyeMusicNexus/public/signup.html',
      musicLegal:'/legal/music-nexus/',
      skyGateLogin:'/admin/login.html',
      support:musicText(store.supportUrl || '', '', 1000)
    },
    boundary:'This public SkyeNet page contains public artist/store metadata and public preview links only. Private stems, masters, protected streams, fulfillment, payout, and admin actions stay inside the shared 0S/SkyGate lane.'
  };
}
