async function musicPublishNetlifyBundle(env, batch, state) {
  const envStatus = musicDropEnvStatus(env);
  const files = musicDropBundleFiles(batch, state);
  const providerRuntimeReceipts = [];
  let providerRuntimeStatus = null;
  const intent = {
    batchId:batch.batchId,
    liveDeployEnabled:envStatus.netlify.liveDeployEnabled,
    netlifyConfigured:envStatus.netlify.configured,
    fileCount:files.length,
    bytes:files.reduce((sum, file) => sum + new TextEncoder().encode(file.body).byteLength, 0),
    createdAt:musicNow(),
  };
  if (!envStatus.netlify.liveDeployEnabled) return {ok:true, published:false, mode:'deploy-intent', intent, reason:'live deploy disabled'};
  const token = routexFirstEnv(env, ['MUSIC_NEXUS_DROPS_NETLIFY_AUTH_TOKEN','NETLIFY_AUTH_TOKEN','SKYGATEFS13_NETLIFY_AUTH_TOKEN','SKYGATEFS13_TARGET_NETLIFY_AUTH_TOKEN']);
  const siteId = routexFirstEnv(env, ['MUSIC_NEXUS_DROPS_NETLIFY_SITE_ID','NETLIFY_SITE_ID','SKYGATEFS13_TARGET_NETLIFY_SITE_ID','SKYEVAULT_DROP_NETLIFY_SITE_ID']);
  if (!token || !siteId) return {ok:false, published:false, mode:'deploy-intent', intent, error:'Netlify token or site ID missing.'};
  const recordProviderRuntime = async ({action, payload = {}} = {}) => {
    const runtime = await musicSkyeNetProviderRuntime(env, {
      providerId:'netlify',
      action,
      usageLane:'skymusicnexus:netlify_deploy',
      customerId:batch.artistId || batch.batchId || '',
      clientId:siteId,
      workspaceId:'music-netlify',
      live:true,
      sandbox:false,
      payload:{...payload, source:'skymusicnexus.netlify_fallback'}
    });
    providerRuntimeStatus = runtime;
    providerRuntimeReceipts.push(runtime);
    return runtime;
  };
  const digests = {};
  for (const file of files) digests[file.path] = await musicSha1Hex(file.body);
  const createRuntime = await recordProviderRuntime({action:'netlify.deploy.create', payload:{site_id:siteId, files:digests, draft:false}});
  const deploy = createRuntime.provider_result || {};
  if (!createRuntime.executed) return {ok:false, published:false, mode:'netlify-api', status:createRuntime.http_status || 502, intent, error:createRuntime.error || 'Netlify deploy create failed.', ...musicSkyeNetRuntimeFields(providerRuntimeReceipts, providerRuntimeStatus)};
  const required = Array.isArray(deploy.required) ? deploy.required : files.map(file => file.path);
  const requiredSet = new Set(required);
  for (const file of files) {
    if (requiredSet.size && !requiredSet.has(file.path)) continue;
    const upload = await recordProviderRuntime({action:'netlify.deploy.file.upload', payload:{deploy_id:deploy.id, path:file.path, content_type:'application/octet-stream', content:file.body}});
    if (!upload.executed) return {ok:false, published:false, mode:'netlify-api', status:upload.http_status || 502, deployId:deploy.id, intent, error:upload.error || `Netlify file upload failed for ${file.path}.`, ...musicSkyeNetRuntimeFields(providerRuntimeReceipts, providerRuntimeStatus)};
  }
  return {ok:true, published:true, mode:'netlify-api', deployId:deploy.id, url:deploy.url || '', state:deploy.status || deploy.state || 'uploaded', fileCount:files.length, bytes:intent.bytes, ...musicSkyeNetRuntimeFields(providerRuntimeReceipts, providerRuntimeStatus)};
}
