    product:{productId:run.productId},
    drop:{dropId:run.dropId, dropUrl},
    release:{releaseId:release.id},
    social:{postId:run.postId},
    stats:{metric:'Nexus streams', source:'music-drops:track-public-event'},
    receiptId,
    hiddenProviderRouting:true,
