function musicCollectiveDefault() {
  const now = musicNow();
  return {
    collectiveId:'gray-skyes-collective',
    id:'gray-skyes-collective',
    slug:'gray-gang',
    name:'Gray Gang',
    previousNames:['Gray Skyes Collective'],
    ownerArtistId:'444666666666',
    ownerName:'Gray Skyes',
    status:'active',
    approvalPolicy:{renameApprovalWindowHours:48, ownerAdminReview:'Skyes Over London admin team can approve sooner; system can auto-approve after the review window.', skyemailAlert:true, auditRequired:true},
    renameRequests:[],
    createdAt:now,
    updatedAt:now
  };
}
function musicEnsureCollectives(state) {
  state.collectives = Array.isArray(state.collectives) ? state.collectives : [];
  const existing = state.collectives.find(item => item.collectiveId === 'gray-skyes-collective' || item.id === 'gray-skyes-collective');
  if (existing) {
    existing.name = existing.name === 'Gray Skyes Collective' ? 'Gray Gang' : (existing.name || 'Gray Gang');
    existing.slug = existing.slug || 'gray-gang';
    existing.previousNames = Array.from(new Set([...(existing.previousNames || []), 'Gray Skyes Collective'].filter(Boolean)));
    existing.approvalPolicy = {...musicCollectiveDefault().approvalPolicy, ...(existing.approvalPolicy || {})};
    existing.updatedAt = existing.updatedAt || musicNow();
    return existing;
  }
  const collective = musicCollectiveDefault();
  state.collectives.unshift(collective);
  return collective;
}
async function musicCollectiveNotify(env, request, access) {
  const subject = `[SkyeMusicNexus] Collective rename review: ${request.currentName} -> ${request.requestedName}`;
  const lines = [
    `Collective rename requested inside SkyeMusicNexus.`,
    `Current: ${request.currentName}`,
    `Requested: ${request.requestedName}`,
    `Collective: ${request.collectiveId}`,
    `Owner artist: ${request.ownerArtistId}`,
    `Requested by: ${request.requestedBy}`,
    `Auto-approve after: ${request.autoApproveAt}`,
    `Status: ${request.status}`,
    `Approve from the gated 0S API: POST /api/skymusicnexus/music-collectives action=approve-rename requestId=${request.requestId}`
  ];
  const result = await sendFree99DemoResendEmail(env, {subject, text:lines.join('\n'), html:`<pre>${musicEscapeHtml(lines.join('\n'))}</pre>`});
  return {ok:result.ok, status:result.status || null, skipped:Boolean(result.skipped), reason:result.reason || null, actor:access.actor || ''};
}
