    const ledger = {
      daemonEventId:musicId('brain_daemon'),
      id:'',
      runId,
      status:'completed',
      source:body.source || 'manual',
      actor:access.actor || 'system',
      profileCount:result.profileCount,
      executedArtistCount:result.executedArtistCount,
      actionCounts:counts,
      streamDelta,
      beforeStreams,
      afterStreams,
      alertIds:alerts.map(alert => alert.alertId || alert.id),
      startedAt:now,
      finishedAt,
      nextTickAt:musicBrainDaemonIsoAfter(policy.cadenceMinutes, Date.parse(finishedAt))
    };
    ledger.id = ledger.daemonEventId;
    daemon.status = 'listening';
    daemon.lastTickAt = finishedAt;
    daemon.nextTickAt = ledger.nextTickAt;
    daemon.heartbeatAt = finishedAt;
    daemon.currentRun = null;
    daemon.lock = null;
    daemon.lastResult = ledger;
    daemon.ledger.unshift(ledger);
    daemon.ledger = daemon.ledger.slice(0, 500);
    daemon.updatedAt = finishedAt;
    for (const alert of alerts) alert.dispatchedAt = alert.dispatchedAt || finishedAt;
    if (alerts.length && ctx?.waitUntil) ctx.waitUntil(musicBrainDaemonDispatchAlerts(env, alerts).catch(() => null));
