    daemon.lock = null;
    daemon.heartbeatAt = musicNow();
    daemon.nextTickAt = musicBrainDaemonIsoAfter(policy.cadenceMinutes);
    daemon.updatedAt = daemon.heartbeatAt;
    alert.dispatchedAt = alert.dispatchedAt || daemon.updatedAt;
    if (ctx?.waitUntil) ctx.waitUntil(musicBrainDaemonDispatchAlerts(env, [alert]).catch(() => null));
