    const settlementId = musicText(body.settlementId || body.id, '', 180);
    const settlement = state.payments.settlements.find(item => item.settlementId === settlementId || item.id === settlementId);
    if (!settlement) return musicJson({ok:false, error:'settlement_not_found'}, 404);
    if (settlement.status !== 'pending_owner_disbursement' && body.ownerOverride !== true) {
      return musicJson({ok:false, error:'settlement_not_ready_for_disbursement', settlement, paperwork:settlement.paperwork || null}, 409);
    }
    const provider = musicText(body.provider || body.disbursementProvider || 'internal_skyepay', 'internal_skyepay', 80).toLowerCase().replace(/[^a-z0-9_ -]+/g, '').replace(/\s+/g, '_');
    const allowedProviders = new Set(['internal_skyepay','paypal','cashapp','zelle','ach_manual','check','other']);
    const disbursementProvider = allowedProviders.has(provider) ? provider : 'other';
    const disbursementId = body.disbursementId || musicId('disbursement');
    const disbursement = {
      id:disbursementId,
      disbursementId,
      settlementId:settlement.settlementId,
      receivableId:settlement.receivableId,
      orderId:settlement.orderId,
      artistId:settlement.artistId,
      amountCents:musicCents(body.amountCents || settlement.payableCents),
      currency:settlement.currency || body.currency || 'USD',
      provider:disbursementProvider,
      destinationLabel:musicText(body.destinationLabel || body.handle || body.reference || '', '', 160),
      externalReference:musicText(body.externalReference || body.referenceId || body.receiptId || '', '', 180),
      status:'completed_owner_recorded',
      recordedBy:musicText(body.recordedBy || '0s-owner', '0s-owner', 120),
      note:musicText(body.note || 'Owner recorded internal/off-platform payout completion.', '', 800),
      createdAt:musicNow(),
      updatedAt:musicNow()
    };
