  const assignments = routexState.assignments.filter(item => routexJobIds.has(item.job_id));
  const assignmentIds = new Set(assignments.map(item => item.id));
  const proofs = routexState.proofItems.filter(item => assignmentIds.has(item.assignment_id));
  const payments = routexState.payments.filter(item => routexJobIds.has(item.job_id) || assignmentIds.has(item.assignment_id));
