    links:links.length,
    open:links.filter(link => !MUSIC_WORKFORCE_TERMINAL_STATUSES.has(link.status)).length,
    assigned:links.filter(link => Number(link.assignmentCount || 0) > 0 || ['assigned','proof_submitted','completed'].includes(link.status)).length,
    completed:links.filter(link => ['completed','closed'].includes(link.status)).length,
    routexJobs:routexJobIds.size,
    assignments:assignments.length,
    proofItems:proofs.length,
